// Embeds the Windows icon and version resources into telegram-agent.exe.
// Does nothing on other targets; icon is generated by scripts/gen_icons.py.
fn main() {
    println!("cargo:rerun-if-changed=assets/icon.ico");
    embed_resources();
}

#[cfg(target_os = "windows")]
fn embed_resources() {
    if !std::path::Path::new("assets/icon.ico").exists() {
        return;
    }
    let mut res = winresource::WindowsResource::new();
    res.set_icon("assets/icon.ico");
    res.set("FileDescription", "Telegram Business Platform");
    res.set("ProductName", "Telegram Agent");
    res.set("LegalCopyright", "MIT License");
    if let Err(e) = res.compile() {
        println!("cargo:warning=windows resource compile failed: {e}");
    }
}

#[cfg(not(target_os = "windows"))]
fn embed_resources() {}
